        /// <summary>
        /// ConvertHtmlToMhtml w/ empty data
        /// </summary>
        [TestMethod]
        public void ConvertHtmlToMhtml_TestWithEmptyData()
        {
            // generates an empty Mhtml, so that can be correctly inserted into the Word doc as a Mht doc, instead of it trying to blow up
            string input = string.Empty;
            string expectedResult = "MIME-Version: 1.0\nContent-Type: multipart/related;\n\ttype=\"text/html\";\n\tboundary=\"dataBoundary\"\n\n--dataBoundary\nContent-Type: text/html;\nContent-Transfer-Encoding: 8bit\n\n<!DOCTYPE html><HTML><HEAD> <style type=\"text/css\">body { line-spacing:100%; line-height: 100%; margin-top: 0; margin-bottom: 0;  } p, div, span {  } </style> </HEAD><BODY></BODY></HTML>\n\n--dataBoundary--";

            string actualResult = RTEUtilities.ConvertHtmlToMhtml(input, null, null, new SpacingDetailsForRTEWordExports());

            Assert.AreEqual(expectedResult, actualResult);
        }

