            string expectedResult = "&nbsp;<table style=\"width:100%\"><tr><td>cell1</td><td>cell2</td><td>cell3</td></tr><tr><td>cell4</td><td>cell5</td><td>cell6</td></tr></table>";
            bool skipCleanup = false;

            string actualResult = RTEUtilities.PrepareHtmlForWordExport(input, false, ref skipCleanup);

            Assert.AreEqual(expectedResult, actualResult);
            Assert.IsTrue(skipCleanup);
        }

        /// <summary>
        /// Tests GetFontSizeBasedOnWordElementXml with both fonts and size provided
        /// </summary>
        [TestMethod]
        public void GetFontSizeBasedOnWordElementXml_TestWithFontAndSize()
        {
            // this was taken from one of the templates, where the font information was present
            string innerXml = "<w:sdtPr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:rPr><w:rFonts w:ascii=\"Arial\" w:hAnsi=\"Arial\" w:cs=\"Arial\" /><w:sz w:val=\"19\" /><w:szCs w:val=\"19\" /></w:rPr><w:alias w:val=\"BOE:BOEDescription\" /><w:tag w:val=\"BOE:BOEDescription\" /><w:id w:val=\"659570154\" /></w:sdtPr><w:sdtEndPr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" /><w:sdtContent xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:r w:rsidR=\"000B4BE8\"><w:rPr><w:rFonts w:ascii=\"Arial\" w:hAnsi=\"Arial\" w:cs=\"Arial\" /><w:sz w:val=\"19\" /><w:szCs w:val=\"19\" /></w:rPr><w:t /></w:r></w:sdtContent>";

            decimal? fontSize = RTEUtilities.GetFontSizeBasedOnWordElementXml(innerXml);
            ICollection<string> fontFamilies = RTEUtilities.GetFontFamiliesBasedOnElementXml(innerXml);

            Assert.IsTrue(fontSize.HasValue);
            Assert.IsTrue(fontSize.Value == (decimal)9.5);

            Assert.IsTrue(fontFamilies.Count == 1);
            Assert.IsTrue(fontFamilies.ElementAt(0) == "Arial");
        }

