        /// <summary>
        /// Tests GetSpacingFromXml with sizing data
        /// </summary>
        [TestMethod]
        public void GetSpacingFromXml_WithSomeData()
        {
            // this was taken from one of the templates, where the font information was present
            string innerXml = "<w:p w:rsidRPr=\"002F1492\" w:rsidR=\"00020287\" w:rsidP=\"00C13177\" w:rsidRDefault=\"004A35E6\" xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:pPr><w:spacing w:before=\"240\" w:after=\"360\" /></w:pPr><w:r w:rsidRPr=\"002F1492\"><w:t /></w:r></w:p>";

            SpacingDetailsForRTEWordExports spacingData = RTEUtilities.GetSpacingFromXml(innerXml);

            Assert.IsTrue(spacingData.Above.Value == 240);
            Assert.IsTrue(spacingData.Below.Value == 360);
            Assert.IsFalse(spacingData.FirstLineIndent.HasValue);
        }

